    biography: "Chris Gottschalk is a General Partner at Mouro Capital, described on the firm's site as a specialist in technology and finance who holds board responsibilities on behalf of Mouro at Upgrade, Blueprint and Trulioo. He joined the firm from Blumberg Capital in 2019, when it was still Santander InnoVentures, and was described as a Senior Advisor in Santander's September 2020 spin-out announcement. Before Blumberg Capital, where he spent seven years as a Principal, he was an investor at Menlo Ventures, held operating roles at early-stage startups, worked as an analyst at Cowen and Company and started his career at Intel. He holds a BA from UC Davis and an MBA from IESE.",
