    biography: "Manuel Silva Martínez is General Partner at Mouro Capital, where the firm's site says he oversees strategy, investor relations, resources and processes as the FCA-authorised General Partner, focusing on UK, Europe and Latin America investments. He spent five years at BBVA Ventures in San Francisco before moving to London in 2015 to join Santander InnoVentures, which he led from 2018. When Banco Santander spun out and renamed the arm as Mouro Capital in September 2020, he became its General Partner. He sits on the boards of a55, bonify and Crosslend. UK Companies House records him as the only individual with significant control over MSM Global Investments LLP, Mouro's FCA-authorised management entity.",
