    biography: "Mathias Schilling is a Founding Partner of Headline, based in the firm's San Francisco office. He describes his path as going from Europe to San Francisco by way of Santa Barbara, co-founding the firm on what he calls blind intuition and a belief in circuitous paths. His investing focus is application software and SaaS alongside consumer. His profile lists more than thirty portfolio companies including Sonos, The RealReal, Groupon, Farfetch, Acorns, Gopuff, Axios, Shipt, BlueKai and Pismo, several of which reached public listings or were acquired by Oracle, Disney, Visa, Target and Cox. He says courage, curiosity and core values are the most important traits in an investor.",
