    biography: "Romero Rodrigues is a Partner at Headline, based in Sao Paulo and focused on Latin America. He founded the consumer internet company Buscape in 1999 and it was acquired in 2009, after which he began investing in 2010. He invests in fintech, ecommerce, software, digital health and media across Brazil and LatAm. His portfolio includes Rappi, Gympass, Olist, Pismo, Sami, Tembici, ViajaNet, Housi and eureciclo. He says he backs bold and ambitious entrepreneurs solving painful problems in huge and inefficient markets, and rates coachability and emotional intelligence as the most important founder traits.",
