    careerTimeline: [],
    biography: "Alon Cinamon is a Principal at Viola Ventures, focusing on cybersecurity and AI infrastructure. Before joining Viola he was an Associate at Ibex Investors covering infrastructure and cybersecurity, and previously an investor at Glilot Capital Partners sourcing cybersecurity and enterprise software startups. He founded VC Club, a nonprofit operating across five Israeli campuses that has helped more than 30 alumni enter the venture industry, and co-founded and hosts The Ecosystem Podcast. He graduated first in his class with highest distinction from Reichman University's honors program. His year of joining Viola Ventures is not disclosed on the fund's site.",
