    biography: "Efayomi Carr is an Investment Partner at Flourish Ventures based in Nairobi, covering Africa and the Middle East. He was previously Head of Strategic Finance and then Interim CFO at Lori, managing a finance team of 15 across multiple geographies, and before that was an Africa venture investor at Quona Capital. Earlier he was an Associate at Boston Consulting Group and Head of Marketplace at Jumia, where Flourish says he grew the division to roughly a quarter of platform revenue. In 2015 he was seconded for six months to the Government of Sierra Leone as a senior official leading data management during the Ebola response, and he co-founded Transparent Nigeria, a digital journalism and data sharing platform. Flourish lists his current investments including Apollo Agriculture, FairMoney, Flash, HoneyCoin, littlefish, Lua, MaxAB, MoneyHash and Pula. He holds an MBA from Harvard Business School and an undergraduate degree from the University of Pennsylvania.",
